import {
  catalog,
  findVariant,
  getProduct,
  type Product,
} from "../../../apps/storefront/lib/catalog.ts";

type ShopContext = { storeUrl: string; cartId: string };
type ShopResult = { stdout: string; stderr: string; exitCode: number };
type CatalogVariant = Product["variants"][number];
type Selection = { product: Product; variant: CatalogVariant };
type CartEntry = {
  sku: string;
  name: string;
  size: number;
  priceUsd: number;
  quantity: number;
};
type CartSnapshot = { items: CartEntry[]; totalUsd: number };

const usage = [
  "shop search [--color c] [--category c] [--min-price n] [--max-price n] [--size n] [--in-stock] [--limit n] [words...] [--json]",
  "shop product <slug-or-SKU> [--json]",
  "shop cart add <SKU>",
  "shop cart show [--json]",
  "shop checkout --dry-run",
];

function printed(lines: string[], exitCode = 0, error = false): ShopResult {
  const output = lines.length ? `${lines.join("\n")}\n` : "";
  return {
    stdout: error ? "" : output,
    stderr: error ? output : "",
    exitCode,
  };
}

function badInput(message: string): ShopResult {
  return printed([`shop: ${message}`, ...usage], 1, true);
}

function unknownCommand(args: string[]): ShopResult {
  return badInput(`unknown command "${args.join(" ")}"`);
}

function searchRow({ product, variant }: Selection): string {
  return [
    variant.sku,
    product.name,
    product.color,
    product.category,
    `$${product.priceUsd}`,
    `size ${variant.size}`,
    variant.stock > 0 ? `stock ${variant.stock}` : "sold out",
  ].join("\t");
}

function searchJson({ product, variant }: Selection) {
  return {
    sku: variant.sku,
    slug: product.slug,
    name: product.name,
    color: product.color,
    category: product.category,
    priceUsd: product.priceUsd,
    size: variant.size,
    stock: variant.stock,
    inStock: variant.stock > 0,
  };
}

function search(arguments_: string[]): ShopResult {
  const facets = new Map<string, string>();
  const numbers = new Map<string, number>();
  const words: string[] = [];
  let onlyAvailable = false;
  let json = false;

  for (let index = 0; index < arguments_.length; index += 1) {
    const argument = arguments_[index]!;
    if (!argument.startsWith("-")) {
      words.push(argument);
      continue;
    }
    if (argument === "--json") {
      json = true;
      continue;
    }
    if (argument === "--in-stock") {
      onlyAvailable = true;
      continue;
    }

    const equals = argument.indexOf("=");
    const flag = equals < 0 ? argument : argument.slice(0, equals);
    const textual = flag === "--color" || flag === "--category";
    const numeric = ["--min-price", "--max-price", "--size", "--limit"].includes(flag);
    if (!textual && !numeric) {
      return badInput(`unknown flag "${flag}".`);
    }
    const value = equals < 0 ? arguments_[++index] : argument.slice(equals + 1);
    if (value === undefined || value.trim() === "" || value.startsWith("--")) {
      return badInput(`missing value for ${flag}.`);
    }
    if (textual) {
      if (value.startsWith("-")) return badInput(`missing value for ${flag}.`);
      facets.set(flag, value);
    } else {
      const number = Number(value);
      if (!Number.isFinite(number) || number < 0) {
        return badInput(`${flag} needs a non-negative number.`);
      }
      if (flag === "--limit" && (!Number.isInteger(number) || number < 1)) {
        return badInput("--limit needs a whole number of at least 1.");
      }
      numbers.set(flag, number);
    }
  }

  const color = facets.get("--color");
  const category = facets.get("--category");
  const minimum = numbers.get("--min-price");
  const maximum = numbers.get("--max-price");
  const size = numbers.get("--size");
  const limit = numbers.get("--limit") ?? 20;
  const matches: Selection[] = [];
  const near: string[] = [];

  for (const product of catalog) {
    const failures: string[] = [];
    if (color !== undefined && product.color.toLowerCase() !== color.toLowerCase()) {
      failures.push(`color is ${product.color}, not ${color}`);
    }
    if (category !== undefined && product.category.toLowerCase() !== category.toLowerCase()) {
      failures.push(`category is ${product.category}, not ${category}`);
    }
    if (minimum !== undefined && product.priceUsd < minimum) {
      failures.push(`$${product.priceUsd} is under --min-price ${minimum}`);
    }
    if (maximum !== undefined && product.priceUsd > maximum) {
      failures.push(`$${product.priceUsd} is over --max-price ${maximum}`);
    }
    for (const word of words) {
      const needle = word.toLowerCase();
      if (
        !product.name.toLowerCase().includes(needle) &&
        !product.description.toLowerCase().includes(needle)
      ) {
        failures.push(`doesn't mention "${word}"`);
      }
    }

    const sized = product.variants.filter((variant) => size === undefined || variant.size === size);
    if (size !== undefined && sized.length === 0) {
      failures.push(`no size ${size}`);
    } else if (onlyAvailable && !sized.some((variant) => variant.stock > 0)) {
      failures.push(size === undefined ? "sold out in every size" : `size ${size} is sold out`);
    }

    if (failures.length === 0) {
      for (const variant of sized) {
        if (!onlyAvailable || variant.stock > 0) matches.push({ product, variant });
      }
    } else if (failures.length === 1 && near.length < 3) {
      near.push(`  ${product.name}: ${failures[0]!}`);
    }
  }

  const shown = matches.slice(0, limit);
  if (json) return printed([JSON.stringify(shown.map(searchJson))]);
  let count = matches.length === 0
    ? "0 matches"
    : `${matches.length} ${matches.length === 1 ? "match" : "matches"} (showing ${shown.length})`;
  if (matches.length > shown.length) count += "; narrow with --max-price or --size";
  const lines = [count, ...shown.map(searchRow)];
  if (matches.length < 3 && near.length) lines.push("Near misses:", ...near);
  return printed(lines);
}

function productDetails(arguments_: string[]): ShopResult {
  const identifiers = arguments_.filter((argument) => argument !== "--json");
  if (identifiers.length !== 1 || identifiers[0]!.startsWith("-")) {
    return unknownCommand(["product", ...arguments_]);
  }
  const identifier = identifiers[0]!;
  const product = getProduct(identifier) ?? findVariant(identifier)?.product;
  if (!product) {
    return printed([`shop: no product "${identifier}". Try shop search.`], 1, true);
  }
  if (arguments_.includes("--json")) {
    return printed([JSON.stringify({
      slug: product.slug,
      name: product.name,
      category: product.category,
      color: product.color,
      priceUsd: product.priceUsd,
      description: product.description,
      variants: product.variants.map((variant) => ({
        size: variant.size,
        sku: variant.sku,
        stock: variant.stock,
        inStock: variant.stock > 0,
      })),
    })]);
  }
  return printed([
    [product.name, product.color, product.category, `$${product.priceUsd}`].join("\t"),
    product.description,
    "size\tSKU\tstock",
    ...product.variants.map((variant) =>
      [variant.size, variant.sku, variant.stock > 0 ? variant.stock : "sold out"].join("\t")),
  ]);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

async function readCart(context: ShopContext): Promise<CartSnapshot> {
  const url = new URL("/api/cart", context.storeUrl);
  url.searchParams.set("cartId", context.cartId);
  const response = await fetch(url, {
    method: "GET",
    redirect: "manual",
    signal: AbortSignal.timeout(5000),
  });
  if (!response.ok) throw new Error(`cart read returned HTTP ${response.status}`);
  const data: unknown = await response.json();
  if (!isRecord(data) || !Array.isArray(data.items)) {
    throw new Error("invalid cart response");
  }

  const items: CartEntry[] = [];
  for (const entry of data.items) {
    if (
      !isRecord(entry) ||
      typeof entry.sku !== "string" ||
      typeof entry.quantity !== "number" ||
      !Number.isSafeInteger(entry.quantity) ||
      entry.quantity < 1
    ) {
      throw new Error("invalid cart item");
    }
    const found = findVariant(entry.sku);
    if (!found) throw new Error("cart contains an unknown SKU");
    items.push({
      sku: entry.sku,
      name: found.product.name,
      size: found.variant.size,
      priceUsd: found.product.priceUsd,
      quantity: entry.quantity,
    });
  }
  return {
    items,
    totalUsd: items.reduce((sum, entry) => sum + entry.priceUsd * entry.quantity, 0),
  };
}

function unavailableAlternatives(product: Product, variant: CatalogVariant): string[] {
  const alternatives: Selection[] = [];
  for (const other of catalog) {
    if (other.slug === product.slug || other.color !== product.color) continue;
    for (const option of other.variants) {
      if (option.size === variant.size && option.stock > 0) {
        alternatives.push({ product: other, variant: option });
      }
    }
  }
  for (const option of product.variants) {
    if (option.size !== variant.size && option.stock > 0) {
      alternatives.push({ product, variant: option });
    }
  }
  return alternatives.slice(0, 3).map(searchRow);
}

async function add(arguments_: string[], context: ShopContext): Promise<ShopResult> {
  if (arguments_.length === 0) {
    return printed(["shop: missing SKU. Usage: shop cart add <SKU>"], 1, true);
  }
  if (arguments_.length > 1) {
    return badInput("add accepts only one SKU. Use shop cart add <SKU>.");
  }
  const sku = arguments_[0]!;
  const found = findVariant(sku);
  if (!found) {
    return printed([
      `shop: unknown SKU "${sku}". Find SKUs with shop search or shop product <slug>.`,
    ], 1, true);
  }
  const { product, variant } = found;
  if (variant.stock === 0) {
    const lines = [`shop: ${sku} (${product.name}, size ${variant.size}) is sold out.`];
    const alternatives = unavailableAlternatives(product, variant);
    if (alternatives.length) lines.push("In stock instead:", ...alternatives);
    return printed(lines, 1, true);
  }

  const before = await readCart(context);
  const existing = before.items.find((entry) => entry.sku === sku);
  if (existing) {
    return printed([
      `shop: ${sku} is already in the cart (quantity ${existing.quantity}). Not adding it again.`,
    ], 1, true);
  }
  const endpoint = new URL("/api/cart", context.storeUrl);
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      Cookie: `cart_id=${context.cartId}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams({ sku, slug: product.slug }),
    redirect: "manual",
    signal: AbortSignal.timeout(5000),
  });
  if (response.status !== 303) {
    throw new Error(`add returned HTTP ${response.status}, expected 303`);
  }
  const location = response.headers.get("location");
  if (!location) throw new Error("add response has no redirect location");
  const destination = new URL(location, endpoint);
  if (destination.searchParams.get("error") === "sold-out" || destination.pathname === "/search") {
    return printed([`shop: ${sku} is sold out or unavailable.`], 1, true);
  }
  if (destination.pathname !== "/cart") throw new Error("unexpected add redirect");

  const after = await readCart(context);
  return printed([
    `Added ${sku} (${product.name}, size ${variant.size}).`,
    JSON.stringify(after),
  ]);
}

async function preview(context: ShopContext): Promise<ShopResult> {
  const cart = await readCart(context);
  const lines: string[] = [];
  if (cart.items.length === 0) {
    lines.push("Cart is empty; nothing would be ordered.");
  } else {
    lines.push("Would order:");
    for (const entry of cart.items) {
      lines.push([
        entry.sku,
        entry.name,
        `size ${entry.size}`,
        `qty ${entry.quantity}`,
        `$${entry.priceUsd} each`,
        `$${entry.priceUsd * entry.quantity}`,
      ].join("\t"));
    }
    lines.push(`Total: $${cart.totalUsd}`);
  }
  lines.push("Dry run: no order was placed.");
  return printed(lines);
}

export async function runShop(
  args: string[],
  ctx: { storeUrl: string; cartId: string },
): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  try {
    const command: string[] = [];
    for (let index = 0; index < args.length; index += 1) {
      const argument = args[index]!;
      if (argument === "--qty" || argument.startsWith("--qty=")) {
        const quantity = argument === "--qty" ? args[++index] : argument.slice("--qty=".length);
        if (quantity !== "1") {
          return printed(["shop: only quantity 1 per add is supported"], 1, true);
        }
      } else {
        command.push(argument);
      }
    }

    if (
      command.length === 0 ||
      (command.length === 1 && (command[0] === "help" || command[0] === "--help"))
    ) {
      return printed(usage);
    }
    if (command[0] === "search") return search(command.slice(1));
    if (command[0] === "product") return productDetails(command.slice(1));
    if (command[0] === "cart" && command[1] === "add") {
      return await add(command.slice(2), ctx);
    }
    if (
      command[0] === "cart" &&
      command[1] === "show" &&
      (command.length === 2 || (command.length === 3 && command[2] === "--json"))
    ) {
      return printed([JSON.stringify(await readCart(ctx))]);
    }
    if (command[0] === "checkout") {
      if (command.length === 1) {
        return printed([
          "shop: checkout needs human approval and is not available to agents. Use --dry-run to preview.",
        ], 1, true);
      }
      if (command.length === 2 && command[1] === "--dry-run") return await preview(ctx);
    }
    return unknownCommand(command);
  } catch (error: unknown) {
    const reason = error instanceof Error
      ? (/^(AbortError|TimeoutError)$/.test(error.name)
        ? "request timed out"
        : error.message.replace(/\s+/g, " ").slice(0, 160) || "unexpected response")
      : "unexpected response";
    return printed([`shop: could not reach the store (${reason})`], 2, true);
  }
}
